#!/bin/bash
# Differential test: compare a Rust binary against the C++ reference byte-for-byte.
# usage: difftest.sh /path/to/rust_binary [cases_file]
REF=/workspace/dataset/test14_executable
RUST="$1"
CASES="${2:-/tmp/harness/cases_quick.txt}"
[ -x "$RUST" ] || { echo "FATAL: rust binary '$RUST' not executable"; exit 2; }
total=0; bad=0
while IFS= read -r line; do
  [ -z "$line" ] && continue
  if [ "$line" = "NOARG" ]; then set --; else eval "set -- $line"; fi
  ro=$("$REF" "$@" 2>/tmp/harness/.re); rc=$?; re=$(cat /tmp/harness/.re)
  uo=$("$RUST" "$@" 2>/tmp/harness/.ue); uc=$?; ue=$(cat /tmp/harness/.ue)
  total=$((total+1))
  if [ "$ro" != "$uo" ] || [ "$rc" != "$uc" ] || [ "$re" != "$ue" ]; then
    bad=$((bad+1))
    echo "=== MISMATCH args: $line"
    echo "  ref exit=$rc rust exit=$uc"
    [ "$ro" != "$uo" ] && { echo "  ref stdout: $(printf '%s' "$ro" | od -c | head -4)"; echo "  rst stdout: $(printf '%s' "$uo" | od -c | head -4)"; }
    [ "$re" != "$ue" ] && { echo "  ref stderr: [$re]"; echo "  rst stderr: [$ue]"; }
  fi
done < "$CASES"
echo "TOTAL=$total MISMATCHES=$bad"
[ $bad -eq 0 ] && echo "RESULT: PASS" || echo "RESULT: FAIL"
exit $([ $bad -eq 0 ] && echo 0 || echo 1)

