#!/bin/bash
REF=/workspace/dataset/test14_executable
w32(){ local v; v=$(( ((($1 % 4294967296)+4294967296)%4294967296) )); [ "$v" -ge 2147483648 ] && v=$((v-4294967296)); echo "$v"; }
predm(){ local n=$1; local m=$2; local k; k=$((n/2)); local slot; slot=$(( ((k%m)+m)%m ));
  if [ $slot -eq 0 ]; then w32 $((n*20)); elif [ $slot -eq 1 ]; then w32 $((n*30)); else w32 $((n*10)); fi; }
d31=0;d127=0;d15=0;d1024=0; f31=0;f127=0;f15=0;f1024=0; fclamp=0; dclamp=0; f63=0; vac=0; tot=0
while read -r n; do
  [ -z "$n" ] && continue
  tot=$((tot+1))
  l2=$("$REF" "$n" | sed -n 2p)
  p64=$(predm $n 64); p32=$(predm $n 32); p128=$(predm $n 128); p16=$(predm $n 16); p1024=$(predm $n 1024)
  clamp=$(w32 $((n*20)))          # rival: idx clamped/ignored -> always reads tail[0]
  x10=$(w32 $((n*10))); x20=$(w32 $((n*20))); x30=$(w32 $((n*30)))
  [ "$x10" = "$x20" ] && [ "$x20" = "$x30" ] && { vac=$((vac+1)); echo "VACUOUS n=$n (n*10==n*20==n*30==$x10)"; }
  [ "$l2" != "$p64" ] && { f63=$((f63+1)); echo "SPEC-FAIL n=$n ref=$l2 pred=$p64"; }
  [ "$p32"  != "$p64" ] && { d31=$((d31+1));   [ "$l2" != "$p32" ]  && f31=$((f31+1)); }
  [ "$p128" != "$p64" ] && { d127=$((d127+1)); [ "$l2" != "$p128" ] && f127=$((f127+1)); }
  [ "$p16"  != "$p64" ] && { d15=$((d15+1));   [ "$l2" != "$p16" ]  && f15=$((f15+1)); }
  [ "$p1024" != "$p64" ] && { d1024=$((d1024+1)); [ "$l2" != "$p1024" ] && f1024=$((f1024+1)); }
  [ "$clamp" != "$p64" ] && { dclamp=$((dclamp+1)); [ "$l2" != "$clamp" ] && fclamp=$((fclamp+1)); }
done < "$1"
echo "TOTAL=$tot spec(leaf64)_failures=$f63"
echo "leaf32:  discriminating_cases=$d31   failures=$f31"
echo "leaf128: discriminating_cases=$d127  failures=$f127"
echo "leaf16:  discriminating_cases=$d15   failures=$f15"
echo "leaf1024:discriminating_cases=$d1024 failures=$f1024"
echo "clamp-to-0 rival: discriminating_cases=$dclamp failures=$fclamp"
EOF
